 const feature='body-shape',requestId=crypto.randomUUID(),job='ai-old-body',imageId=crypto.randomUUID(),legacy={aspectRatio:'4:5',resolution:'2K',gender:'女性',bodyShape:'筋肉質'},pending={requestId,originJob:job,brief:'old body',referenceNote:'',inputState:legacy,materialSlots:[]};const t=await mount(feature,{job,pending});try{const raw=[...session.entries()];await t.call(()=>t.f.current.setInputState(chooseModelCustomBody(legacy,true)));assert.deepEqual([...session.entries()],raw);assert.deepEqual(t.f.current.inputState,legacy);t.f.readReceipt={success:true,requestId,state:'completed',jobId:job,provider:'workers_ai',persistenceStatus:'completed',requestedCandidateCount:1,persistedCandidateCount:1,matrix:[{bodyType:'regular',ageGroup:'20s',imageId,storagePath:'generated-images/'+imageId,imageUrl:'https://fixture.invalid/'+imageId,jobId:job,persistenceStatus:'completed',provider:'workers_ai'}]};await t.call(()=>t.f.current.reconcile());assert.equal(t.f.reads,1);assert.equal(t.f.calls.length,0);assert.equal(t.f.current.result.imageId,imageId);assert.equal(t.f.current.status,'unavailable');assert.deepEqual(t.f.current.inputState,legacy);assert.deepEqual(t.f.persists[0].metadata.inputState,legacy);assert.equal(session.size,0);}finally{await t.close();}
