test('Library stale callback/auth and custom-mode changes during signing cannot replace source or dispatch',async()=>{
 const old=await mount('model-face');try{await old.sources();const stale=old.f.current.selectModelReference;old.f.auth=auth('new-owner');await old.render();const after=structuredClone(old.f.current.slots),count=old.f.signCalls.length;await old.call(()=>stale({imageUrl:'https://expired.invalid',imageId:'old-owner-reference',storagePath:'generated-images/old-owner-reference'}));assert.deepEqual(old.f.current.slots,after);assert.equal(old.f.signCalls.length,count);assert.equal(old.f.calls.length,0);}finally{await old.close();}
 for(const reason of ['auth','custom']){const feature=reason==='custom'?'pose-change':'model-face',t=await mount(feature);try{await t.sources();const before=structuredClone(t.f.current.slots.secondary);t.f.holdSigning=true;let pick:Promise<void>;await act(async()=>{pick=t.f.current.selectModelReference({imageUrl:'https://expired.invalid',imageId:'inflight-reference',storagePath:'generated-images/inflight-reference'});await Promise.resolve();});assert.equal(typeof t.f.releaseSigning,'function');if(reason==='auth'){t.f.auth=auth('other-owner');await t.render();}else await t.call(()=>t.f.current.setInputState({...t.f.current.inputState,inputMode:'custom',customDescription:'Current draft'}));const after=structuredClone(t.f.current.slots);t.f.releaseSigning();await t.call(()=>pick!);assert.deepEqual(t.f.current.slots,after);if(reason==='custom')assert.deepEqual(t.f.current.slots.secondary,before);assert.equal(t.f.calls.length,0);assert.equal(t.f.persists.length,0);}finally{await t.close();}}
});
