for(const feature of ['pose-change','background-change'])test(`${feature}: old pending snapshot never rewritten by explicit mode setter; no dispatch`,async()=>{const legacy={aspectRatio:'4:5',resolution:'2K'},pending={requestId:crypto.randomUUID(),originJob:null,brief:'old pending',referenceNote:'OLD_NOTE',inputState:legacy,materialSlots:[]};const t=await mount(feature,{pending});try{const raw=[...session.entries()];assert.deepEqual(t.f.current.inputState,legacy);await t.call(()=>t.f.current.setInputState({...legacy,inputMode:'custom',customDescription:'new draft'}));assert.deepEqual(t.f.current.inputState,legacy);assert.deepEqual([...session.entries()],raw);assert.equal(t.f.calls.length,0);assert.equal(t.f.persists.length,0);}finally{await t.close();}});
test('held custom request ignores live mode/description changes after async dispatch; pending and save use original snapshot',async()=>{const feature='pose-change',seed=modeArtifact(feature,defaultModelToolSettings(feature));const t=await mount(feature,{artifact:seed,job:seed.sourceJobId,hold:true});try{const settings={...defaultModelToolSettings(feature),inputMode:'custom',customDescription:'SNAPSHOT_DESCRIPTION'};await t.call(()=>t.f.current.setInputState(settings));let promise:Promise<any>;await act(async()=>{promise=t.f.current.generate({brief:'Snapshot'});await Promise.resolve();});await t.settle();assert.equal(t.f.calls.length,1);await t.call(()=>t.f.current.setInputState({...settings,inputMode:'reference',customDescription:'LIVE'}));t.f.current.inputState.inputMode='reference';t.f.current.inputState.customDescription='LIVE';t.f.release();await t.call(()=>promise!);assert(t.f.calls[0].body.productDescription.includes('SNAPSHOT_DESCRIPTION'));assert(!Object.hasOwn(t.f.calls[0].body,'modelReferenceImageUrl'));assert.deepEqual(t.f.persists[0].metadata.inputState,settings);assert.equal(t.f.persists[0].metadata.materialSlots.length,2);}finally{await t.close();}});
for(const feature of ['pose-change','background-change'])test(`${feature}: custom draft with missing primary never promotes availability or dispatches`,async()=>{
 const settings={...defaultModelToolSettings(feature),inputMode:'custom',customDescription:'current description'},artifact=modeArtifact(feature,settings),missing='local-canvas-asset://missing-custom-primary';artifact.metadata.materialSlots[0]={key:'primary',fileName:'primary',materialKind:'primary',imageUrl:missing} as any;
 const t=await mount(feature,{artifact,job:artifact.sourceJobId,missingSources:[missing]});try{const identity=structuredClone(t.f.current.result);assert.equal(t.f.current.slots.primary,null);assert.equal(t.f.current.inputsAvailable,false);await t.call(()=>t.f.current.setInputState({...settings,customDescription:'edited description'}));assert.equal(t.f.current.inputsAvailable,false);assert.equal(t.f.current.originalInputsAvailable,false);assert.equal(t.f.current.status,'unavailable');assert.deepEqual(t.f.current.result,identity);await t.call(()=>t.f.current.generate({brief:'missing primary'}));assert.equal(t.f.calls.length,0);assert.equal(t.f.persists.length,0);assert.equal(t.f.acks.length,0);}finally{await t.close();}
});
